Here's a JavaScript regex pattern that validates a strong password:

```javascript
// Strong password validation
function validatePassword(password) {
    // At least 8 characters, at least one uppercase letter,
    // one lowercase letter, one number, and one special character
    const strongPasswordRegex = /^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)(?=.*[!@#$%^&*()_+\-=\[\]{};':"\\|,.<>\/?]).{8,}$/;
    return strongPasswordRegex.test(password);
}

// With individual checks for better error messages
function validatePasswordDetailed(password) {
    const errors = [];

    if (password.length < 8) {
        errors.push('Password must be at least 8 characters long');
    }
    if (!/[a-z]/.test(password)) {
        errors.push('Password must contain at least one lowercase letter');
    }
    if (!/[A-Z]/.test(password)) {
        errors.push('Password must contain at least one uppercase letter');
    }
    if (!/\d/.test(password)) {
        errors.push('Password must contain at least one number');
    }
    if (!/[!@#$%^&*()_+\-=\[\]{};':"\\|,.<>\/?]/.test(password)) {
        errors.push('Password must contain at least one special character');
    }

    return {
        valid: errors.length === 0,
        errors: errors
    };
}

// Example usage
console.log(validatePassword('Weak1'));          // false (too short)
console.log(validatePassword('StrongPass1!'));   // true
console.log(validatePassword('nouppercase1!'));  // false (no uppercase)

const result = validatePasswordDetailed('Test123!');
console.log(result.valid);   // false
console.log(result.errors);  // ['Password must be at least 8 characters long']
```

The regex uses lookahead assertions `(?=...)` to check multiple conditions without consuming characters. The `.{8,}$` ensures minimum length. Common special characters for passwords include: `!@#$%^&*()_+-=[]{};':"|,.<>/?`. Adjust the character class to match your specific requirements.
